package com.senniaf.match;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.http.HttpMethod;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
@org.springframework.context.annotation.Import(PruebasProgramacionConfig.class)
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
@EnabledIfEnvironmentVariable(named="HU19_TEST_DB_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/hu19_[a-z_]+")
class CombinacionesRechazadasPostgresIT extends SoportePostgresIT {
 @org.springframework.beans.factory.annotation.Autowired PruebasProgramacionConfig.Reloj reloj;
 boolean recomendado(Caso c){var r=datos(req("/api/scoring/casos/"+c.n().getCodigoCaso(),HttpMethod.GET,comite,null));for(var f:r.path("familias"))if(f.path("codigo").asText().equals(c.f().getCodigoCaso()))return true;return false;}
 @Test void rechazoComiteExcluyeSoloLaCombinacionConservandoHistorial(){Caso c=caso(),otra=caso();assertTrue(recomendado(c));long v=vinculaciones.count();var r=req("/api/scoring/casos/"+c.n().getCodigoCaso()+"/decisiones",HttpMethod.POST,comite,Map.of("familia",c.f().getCodigoCaso(),"decision","DESCARTADA","motivo","El Comité selecciona otras alternativas de acompañamiento"));assertEquals(200,r.getStatusCode().value(),r.getBody());assertFalse(recomendado(c));assertEquals(v,vinculaciones.count());assertEquals(409,aceptar(c.n(),c.f()).getStatusCode().value());var nuevaInfantil=aceptar(c.n(),otra.f());assertEquals(200,nuevaInfantil.getStatusCode().value(),nuevaInfantil.getBody());var nuevaFamiliar=aceptar(otra.n(),c.f());assertEquals(200,nuevaFamiliar.getStatusCode().value(),nuevaFamiliar.getBody());assertEquals("DESCARTADA",decisiones.findByCodigoNinoOrderByFechaAsc(c.n().getCodigoCaso()).get(0).getDecision());}
 @Test void rechazoFamiliarExcluyeParYLiberaPropuestaSinCierreArtificial(){Caso c=caso(),otra=caso();long id=asignar(c);var respuesta=req("/api/vinculaciones/"+id+"/respuesta",HttpMethod.POST,c.token(),Map.of("respuesta","RECHAZAR"));assertEquals(200,respuesta.getStatusCode().value(),respuesta.getBody());var v=vinculaciones.findById(id).orElseThrow();assertEquals("RECHAZADA_POR_FAMILIA",v.getEstado().name());assertFalse(v.isReservaVigente());assertFalse(datos(req("/api/familias/mi-perfil",HttpMethod.GET,c.token(),null)).path("vinculacionAceptada").asBoolean());assertNull(v.getFechaCierre());assertFalse(recomendado(c));assertEquals(409,aceptar(c.n(),c.f()).getStatusCode().value());var nuevaInfantil=aceptar(c.n(),otra.f());assertEquals(200,nuevaInfantil.getStatusCode().value(),nuevaInfantil.getBody());var nuevaFamiliar=aceptar(otra.n(),c.f());assertEquals(200,nuevaFamiliar.getStatusCode().value(),nuevaFamiliar.getBody());assertFalse(ninos.findById(c.n().getId()).orElseThrow().isBajaLogica());assertEquals(403,req("/api/vinculaciones/"+id,HttpMethod.GET,c.token(),null).getStatusCode().value());}
 @Test void rechazosDuplicadosNoCreanDosDecisiones() throws Exception {Caso c=caso();String ruta="/api/scoring/casos/"+c.n().getCodigoCaso()+"/decisiones";var body=Map.of("familia",c.f().getCodigoCaso(),"decision","DESCARTADA","motivo","Revisión institucional concurrente de la propuesta");assertEquals(List.of(200,409),simultaneas(()->req(ruta,HttpMethod.POST,comite,body),()->req(ruta,HttpMethod.POST,comite,body)));assertEquals(1,decisiones.findByCodigoNinoOrderByFechaAsc(c.n().getCodigoCaso()).size());}
 @Test void apiSinVersionNoPuedeDecidir(){Caso c=caso();var h=new org.springframework.http.HttpHeaders();h.setBearerAuth(comite);h.setContentType(org.springframework.http.MediaType.APPLICATION_JSON);var r=http.exchange("/api/scoring/casos/"+c.n().getCodigoCaso()+"/decisiones",HttpMethod.POST,new org.springframework.http.HttpEntity<>(Map.of("familia",c.f().getCodigoCaso(),"decision","ACEPTADA","motivo","Esta solicitud no contiene la versión del análisis"),h),String.class);assertEquals(409,r.getStatusCode().value());assertTrue(decisiones.findByCodigoNinoOrderByFechaAsc(c.n().getCodigoCaso()).isEmpty());}
 @Test void rechazoHistoricoSigueExcluidoTrasCambiarPesos(){
  Caso c=caso();var d=new com.senniaf.match.model.DecisionComite();d.setCodigoNino(c.n().getCodigoCaso());d.setCodigoFamilia(c.f().getCodigoCaso());d.setDecision("DESCARTADA");d.setFuncionario("HU19-CM");d.setMotivo("Rechazo histórico sintético conservado antes del cambio de pesos");d.setFecha(java.time.LocalDateTime.now().minusDays(10));d.setPuntaje(65);d.setVersionPesos(1);d.setContextoScoring("{\"origen\":\"histórico\"}");d=decisiones.saveAndFlush(d);var id=d.getId();assertFalse(recomendado(c));
  var antes=datos(req("/api/scoring/pesos",HttpMethod.GET,comite,null));var originales=new LinkedHashMap<String,Object>();for(String k:List.of("edad","hermanos","salud","apoyo","logistica"))originales.put(k,antes.path(k).asInt());
  try{
   var cambios=new LinkedHashMap<>(originales);String a=originales.entrySet().stream().filter(e->(Integer)e.getValue()>0).findFirst().orElseThrow().getKey();String b=originales.keySet().stream().filter(k->!k.equals(a)).findFirst().orElseThrow();cambios.put(a,(Integer)cambios.get(a)-1);cambios.put(b,(Integer)cambios.get(b)+1);cambios.put("justificacion","Cambio sintético para comprobar que un rechazo histórico no se reactiva");cambios.put("versionEsperada",antes.path("version").asInt());var r=req("/api/scoring/pesos",HttpMethod.PUT,comite,cambios);assertEquals(200,r.getStatusCode().value(),r.getBody());reloj.avanzar(java.time.Instant.parse(datos(r).path("activarEl").asText()).plusSeconds(1));req("/api/scoring/pesos",HttpMethod.GET,comite,null);assertFalse(recomendado(c));assertEquals(409,aceptar(c.n(),c.f()).getStatusCode().value());var conservada=decisiones.findById(id).orElseThrow();assertEquals(65,conservada.getPuntaje());assertEquals(1,conservada.getVersionPesos());assertEquals("{\"origen\":\"histórico\"}",conservada.getContextoScoring());
  }finally{
   var actual=datos(req("/api/scoring/pesos",HttpMethod.GET,comite,null));originales.put("versionEsperada",actual.path("version").asInt());originales.put("justificacion","Restablecer los pesos sintéticos previos conservando la auditoría");var r=req("/api/scoring/pesos",HttpMethod.PUT,comite,originales);assertEquals(200,r.getStatusCode().value(),r.getBody());reloj.avanzar(java.time.Instant.parse(datos(r).path("activarEl").asText()).plusSeconds(1));req("/api/scoring/pesos",HttpMethod.GET,comite,null);
  }
 }

 @Test void rechazoAnteriorSinActuacionNoVuelveAExigirCierre(){
  var c=caso();long id=asignar(c);
  jdbc.update("update vinculaciones set estado='RESPUESTA_RECHAZADA_PENDIENTE_CIERRE',reserva_vigente=false,fecha_respuesta=now(),respondido_por=? where id=?",c.f().getRegistradoPor(),id);
  jdbc.update("insert into combinaciones_excluidas(codigo_nino,codigo_familia,origen,responsable,fecha) values(?,?,'FAMILIA',?,now())",c.n().getCodigoCaso(),c.f().getCodigoCaso(),c.f().getRegistradoPor());
  var r=datos(req("/api/vinculaciones/"+id,HttpMethod.GET,comite,null));assertEquals("RECHAZADA_POR_FAMILIA",r.path("estado").asText());assertFalse(r.path("puedeCerrar").asBoolean());
  assertEquals("RESPUESTA_RECHAZADA_PENDIENTE_CIERRE",vinculaciones.findById(id).orElseThrow().getEstado().name());assertFalse(recomendado(c));assertEquals(409,aceptar(c.n(),c.f()).getStatusCode().value());
 }

}
